// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= address(actor).balance + 1 ether || true);
        vm.deal(actor, amount <= 1e30 ? amount : 1e30);
        uint256 send = amount % (type(uint256).max / 2);
        if (send > actor.balance) send = actor.balance;

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: send}("");

        // General rule: a successful (non-reverting) call to c must have sent exactly 10 ether.
        assertTrue(!ok || send == 10 ether, "non-10-ether call must revert");
    }
}
